"""
core/i18n.py — Lightweight UI translation layer.

Translation keys are the English source string itself, not abstract IDs, so
any string without a translation entry safely falls back to English instead
of crashing or showing a raw key. Covers the 12 languages offered at
onboarding (core.data.LANGUAGES): en, es, fr, pt, hi, ar, sw, yo, de, ja,
tl, zh. "en" never needs a lookup — it IS the source text.

Usage:
    from core.i18n import t
    st.button(t("Continue"))
    st.caption(t("Step {n} of {total}").format(n=step, total=total))

Translated strings that carry a Python format placeholder (e.g. "{n}") keep
the same placeholder name across every language — only the surrounding
words move.
"""

from __future__ import annotations

# ---------------------------------------------------------------------------
# String table: English source -> {lang_code: translation}
# Organized in sections matching the page each string lives on, in the order
# pages were translated. A string used on multiple pages only needs one entry.
# ---------------------------------------------------------------------------

_STRINGS: dict[str, dict[str, str]] = {}


def _add(strings: dict[str, dict[str, str]]) -> None:
    """Merge a batch of {english: {lang: translation}} into the shared table."""
    _STRINGS.update(strings)


