# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def t(text: str, lang: str | None = None) -> str:
    """
    Translate a UI string into the given language (defaults to the current
    user's profile_language). Falls back to the original English text if
    there's no translation for that language, or no entry for that string.
    """
    if lang is None:
        try:
            import streamlit as st
            lang = st.session_state.get("profile_language", "en")
        except Exception:
            lang = "en"
    if not lang or lang == "en":
        return text
    return _STRINGS.get(text, {}).get(lang, text)
